from taf.rfrl.procedures.resources.python.status_check.cells.Cell import Cell


class NrCell(Cell):

    def __init__(self, variant, connection, cell_id):
        Cell.__init__(self, variant, connection, cell_id)
        self._cell_type = "nr"

    def _get_active_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='enabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "availabilityStatus": self._status_selector.select_availability_status(
                    variant='online',
                    sharing_rmods_state=self.sharing_rmods_state),
                "usageState": "Active",
                "blockingState": "Unblocked",
                "proceduralStatus": "configured",
                "barringStatus": "unbarred",
                "energySavingState": "notEnergySaving"}

    def _get_online_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='enabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "availabilityStatus": self._status_selector.select_availability_status(
                    variant='online',
                    sharing_rmods_state=self.sharing_rmods_state),
                "blockingState": "Unblocked",
                "proceduralStatus": "configured",
                "barringStatus": "unbarred",
                "energySavingState": "notEnergySaving"}

    def _get_offline_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='disabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "availabilityStatus": self._status_selector.select_availability_status(variant='offline'),
                "blockingState": "Unblocked",
                "proceduralStatus": "initializing",
                "barringStatus": "unbarred"}

    def _get_failed_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(
                variant='disabled',
                sharing_rmods_state=self.sharing_rmods_state),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "usageState": "Active" if self.sharing_rmods_state in ("partially_disabled", "unlocked") else "Idle",
                "blockingState": "Unblocked",
                "proceduralStatus": "configured" if self.sharing_rmods_state in ("partially_disabled", "unlocked")
                                    else "not initialized",
                "barringStatus": "unbarred",
                "availabilityStatus": self._status_selector.select_availability_status(
                    variant='failed',
                    is_iot=self.is_iot,
                    sharing_rmods_state=self.sharing_rmods_state)}

    def _get_dependency_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(
            variant='disabled',
            sharing_rmods_state=self.sharing_rmods_state),
            "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
            "usageState": "Active" if self.sharing_rmods_state == "partially_locked" else "Idle",
            "blockingState": "Unblocked",
            "proceduralStatus": "configured",
            "barringStatus": "unbarred",
            "availabilityStatus": self._status_selector.select_availability_status(
                variant='dependency',
                is_iot=self.is_iot,
                sharing_rmods_state=self.sharing_rmods_state)
        }

    def _get_blocked_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='disabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "usageState": "Idle",
                "blockingState": "Blocked",
                "proceduralStatus": "configured",
                "barringStatus": "unbarred",
                "availabilityStatus": self._status_selector.select_availability_status(variant='offline',
                                                                                       is_iot=self.is_iot),
                "energySavingState": "notEnergySaving"}

    def _get_locked_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='disabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='locked'),
                "usageState": "Idle",
                "blockingState": "Unblocked",
                "proceduralStatus": "initialization required",
                "barringStatus": "unbarred",
                "availabilityStatus": self._status_selector.select_availability_status(variant='offline',
                                                                                       is_iot=self.is_iot),
                "energySavingState": "notEnergySaving"}

    def _get_degraded_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='enabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "usageState": "Active",
                "blockingState": "Unblocked",
                "barringStatus": "unbarred",
                "availabilityStatus": self._status_selector.select_availability_status(variant='degraded',
                                                                                       is_iot=self.is_iot),
                "energySavingState": "notEnergySaving"}

    def _get_dedicated_for_rat_reset_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='disabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "usageState": "Idle",
                "barringStatus": "unbarred"}

    def _get_energy_saving_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='disabled'),
                "availabilityStatus": self._status_selector.select_availability_status(variant='offline'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "usageState": "Idle",
                "blockingState": "Unblocked",
                "proceduralStatus": "configured",
                "barringStatus": "unbarred",
                "energySavingState": 'energySaving'}

    def _get_reduced_energy_saving_statuses(self):
        return {"operationalState": self._status_selector.select_operational_state(variant='enabled'),
                "administrativeState": self._status_selector.select_administrative_state(variant='unlocked'),
                "blockingState": "Unblocked",
                "proceduralStatus": "configured",
                "barringStatus": "unbarred",
                "energySavingState": 'reducedEnergySaving'}
